#!/usr/bin/env bash
# Smoke test of a freshly built executable (run by the CI on the Windows runner), on PDFs
# generated by massicot-essais. Usage: essai-windows.sh <massicot.exe> <massicot-essais.exe>
set -euo pipefail
exe="$1" essais="$2"
work="$(mktemp -d)"

out="$("$exe" --version | tr -d '\r')"
echo "$out"
test "$out" = "massicot ${MASSICOT_VERSION:?}"

"$essais" "$work" > /dev/null
"$exe" infos "$work/essai.pdf"
"$exe" infos --json "$work/essai.pdf" | tr -d '\r' | grep -q '"pages": 5'

# Découpe d'essai : 5 pages, un fichier toutes les 2 pages.
"$exe" decouper "$work/essai.pdf" --toutes 2 --dossier "$work/parties"
test "$(ls "$work/parties" | wc -l)" -eq 3
"$exe" infos --json "$work/parties/essai-03.pdf" | tr -d '\r' | grep -q '"pages": 1'

# OCR d'essai avec le moteur intégré : les modèles doivent être trouvés à côté de l'exécutable.
"$exe" texte --ocr jamais --pages 1 "$work/essai-scan.pdf" | tr -d '\r' | grep -q "aucun texte"
"$exe" ocr --moteur integre "$work/essai-scan.pdf" --sortie "$work/cherchable.pdf"
"$exe" texte --ocr jamais --pages 1 "$work/cherchable.pdf" | tr -d '\r' | grep -q "VERBAL"
echo "Essai réussi."
